-- 세트 555. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set555.sql, 05·06·08. docs/specs/spec_pilot_gap_sets.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 555, 'docker context 와 원격 데몬', 'docker 명령이 어느 데몬에 말을 거는지를 정하는 context 를 만들고(ls·create·inspect), 전환하고(use), 일회성으로 지정(--context)하는 것을 직접 해 보고, DOCKER_HOST 환경변수의 우선순위, ssh:// 로 원격 데몬에 붙는 방식, 2375 평문 포트를 열면 안 되는 이유를 익힙니다. 원격 접속은 하지 않고 설정만 다룹니다.', 'docker', '도커'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 555);
UPDATE quest_set SET display_order = 815, unit_id = (SELECT id FROM unit WHERE id = 66), icon = '🔌' WHERE id = 555;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 555, 1, 'context 가 하는 일', '`docker ps` 를 치면 어느 도커 데몬의 컨테이너가 보일지는 무엇이 정하나요? 서버가 여러 대인 운영자가 명령마다 접속 정보를 쓰지 않고 대상을 바꾸고 싶어 합니다.', '도커 CLI 는 데몬이 아니라 "말을 거는 쪽" 입니다. 말 걸 대상의 주소를 이름 붙여 저장해 두는 기능을 찾아 보세요.', NULL, NULL, '[]', 'choice', '["항상 같은 컴퓨터의 데몬만 쓴다", "현재 선택된 context 가 가리키는 데몬 주소(endpoint)로 정해진다", "컨테이너 이름 앞에 서버 이름을 붙여야만 한다", "마지막으로 실행한 컨테이너가 있는 서버로 정해진다"]', 1, 'context 는 "이름 + 데몬 접속 정보(endpoint)" 를 저장한 것입니다. `docker context ls` 로 목록을 보고 `docker context use 이름` 으로 바꾸면, 이후 `docker ps` 등 모든 명령이 그 데몬을 향합니다. 기본 context 이름은 `default` 이고 로컬 소켓을 씁니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 555 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 555, 2, 'ssh 형태 context 만들고 확인하기', '**상황** — 운영 서버 한 대를 원격으로 다루려고 합니다. 오늘은 접속하지 않고 **등록만** 합니다. 이름 `remote-test`, 접속 주소 `ssh://deploy@192.0.2.10`(문서용 예시 주소) 인 context 를 만들고(`--docker "host=..."` 옵션), 설명(`--description`)은 `staging server` 로 하세요. 그런 다음 `docker context inspect` 의 Go 템플릿으로 이 context 의 도커 접속 주소(`{{.Endpoints.docker.Host}}`)만 뽑아 `/tmp/q2.txt` 에 저장하세요.', '`docker context create 이름 --description ... --docker "host=주소"` 형태입니다. inspect 는 `-f` 템플릿과 context 이름을 함께 씁니다. 만들기만 하므로 연결 실패는 나지 않습니다.', 'docker context create remote-test --description ''staging server'' --docker ''host=ssh://deploy@192.0.2.10''
docker context inspect -f ''{{.Endpoints.docker.Host}}'' remote-test > /tmp/q2.txt
cat /tmp/q2.txt

# create 는 설정만 저장한다. 이 시점에는 원격으로 접속하지 않는다', '["sh", "-c", "unset DOCKER_HOST; docker context use default >/dev/null 2>&1; docker context rm -f staging alt remote-test broken >/dev/null 2>&1; docker rm -f $(docker ps -aq) >/dev/null 2>&1; rm -rf /tmp/work /tmp/q*.txt; mkdir -p /tmp/work; docker image inspect alpine >/dev/null 2>&1 || docker pull -q alpine >/dev/null 2>&1; true\\n"]', '["sh", "-c", "( docker context ls --format \\"{{.Name}}\\" | grep -qx remote-test ) && ( docker context inspect remote-test 2>/dev/null | grep -q \\"\\\\\\"Description\\\\\\": \\\\\\"staging server\\\\\\"\\" ) && ( [ \\"$(cat /tmp/q2.txt)\\" = \\"ssh://deploy@192.0.2.10\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "remote-test context 가 있다", "cmd": ["sh", "-c", "docker context ls --format \\"{{.Name}}\\" | grep -qx remote-test"]}, {"label": "설명이 staging server 이다", "cmd": ["sh", "-c", "docker context inspect remote-test 2>/dev/null | grep -q \\"\\\\\\"Description\\\\\\": \\\\\\"staging server\\\\\\"\\""]}, {"label": "저장된 접속 주소가 ssh 주소이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q2.txt)\\" = \\"ssh://deploy@192.0.2.10\\" ]"]}]', '[{"title": "docker context", "url": "https://docs.docker.com/engine/manage-resources/contexts/"}, {"title": "원격 데몬 보호", "url": "https://docs.docker.com/engine/security/protect-access/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 555 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 555, 3, 'ssh:// context 가 동작하는 방식', '`ssh://deploy@192.0.2.10` 로 만든 context 로 `docker ps` 를 실행하면 내부적으로 어떤 일이 일어나나요?', '원격에서는 어떤 프로그램이 실행되어야 하는지, 별도 포트가 필요한지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["원격 서버의 2375 포트로 평문 접속한다", "명령을 로컬에서 실행하고 결과만 원격으로 복사한다", "원격 서버에 도커 데몬이 없어도 된다", "SSH 로 원격 서버에 로그인해 그 서버의 도커 데몬에 연결한다. 원격에서 SSH 접속이 되고 그 계정이 도커를 쓸 수 있어야 한다"]', 3, '`ssh://` endpoint 는 SSH 접속을 통해 원격 도커 소켓에 연결합니다. 그래서 도커 API 포트를 따로 열지 않아도 되고, SSH 키 로그인(비밀번호 입력 없이)이 미리 되어 있어야 하며, 접속 계정이 원격에서 도커를 쓸 권한(docker 그룹)이 있어야 합니다. 또 원격 계정의 PATH 에 docker CLI 도 설치되어 있어야 합니다(내부적으로 원격에서 `docker system dial-stdio` 를 실행합니다).', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 555 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 555, 4, 'context 를 만들어 전환했다가 되돌리기', '**상황** — 여러 context 를 오가다 보면 "지금 어디를 가리키지?" 가 헷갈립니다. 로컬 소켓을 가리키는 context `alt`(`--docker "host=unix:///var/run/docker.sock"`)를 만들고 `docker context use` 로 전환하세요. 전환한 상태에서 **현재 context 이름**(`docker context show`)을 `/tmp/q4.txt` 에 저장하고, 마지막에는 다시 `default` 로 되돌려 놓으세요.', '`docker context use 이름` 으로 전환하고 `docker context show` 가 현재 이름을 한 줄로 출력합니다. 저장 시점이 전환 뒤인지 확인하세요.', 'docker context create alt --docker ''host=unix:///var/run/docker.sock''
docker context use alt
docker context show > /tmp/q4.txt
docker context use default
cat /tmp/q4.txt

# use 는 설정 파일에 기록되어 이후 모든 명령에 적용된다. 끝나면 되돌려 두는 습관이 사고를 막는다', '["sh", "-c", "unset DOCKER_HOST; docker context use default >/dev/null 2>&1; docker context rm -f staging alt remote-test broken >/dev/null 2>&1; docker rm -f $(docker ps -aq) >/dev/null 2>&1; rm -rf /tmp/work /tmp/q*.txt; mkdir -p /tmp/work; docker image inspect alpine >/dev/null 2>&1 || docker pull -q alpine >/dev/null 2>&1; true\\n"]', '["sh", "-c", "( docker context ls --format \\"{{.Name}}\\" | grep -qx alt ) && ( [ \\"$(cat /tmp/q4.txt)\\" = alt ] ) && ( [ \\"$(docker context show)\\" = default ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "alt context 가 만들어졌다", "cmd": ["sh", "-c", "docker context ls --format \\"{{.Name}}\\" | grep -qx alt"]}, {"label": "전환했을 때의 이름 alt 가 저장되어 있다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q4.txt)\\" = alt ]"]}, {"label": "지금은 default 로 되돌아와 있다", "cmd": ["sh", "-c", "[ \\"$(docker context show)\\" = default ]"]}]', '[{"title": "docker context", "url": "https://docs.docker.com/engine/manage-resources/contexts/"}, {"title": "원격 데몬 보호", "url": "https://docs.docker.com/engine/security/protect-access/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 555 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 555, 5, 'DOCKER_HOST 와 context 의 우선순위', '`docker context use staging` 으로 원격 context 를 선택해 둔 터미널에서 `export DOCKER_HOST=unix:///var/run/docker.sock` 를 실행했습니다. 이 터미널의 `docker ps` 는 어디를 향하나요?', '"더 가까이 지정한 값이 이긴다" 는 원칙을 떠올리되, 환경변수와 `docker context use` 가 저장한 값 중 무엇이 더 앞서는지 따져 보세요.', NULL, NULL, '[]', 'choice', '["context 가 이겨서 staging 의 원격 데몬을 향한다", "DOCKER_HOST 가 이겨서 로컬 소켓을 향한다 (context 선택은 무시된다)", "두 설정이 충돌해 오류가 난다", "두 데몬 모두에 명령이 간다"]', 1, '환경변수 `DOCKER_HOST` 가 설정되어 있으면 `docker context use` 로 고른 context 보다 우선합니다. 그래서 context 를 바꿨는데 엉뚱한 곳에 명령이 가면 `echo $DOCKER_HOST` 를 먼저 확인해야 합니다. 더 강한 것은 명령줄 `--context`(또는 `-H`)로, 이 명령 한 번만 대상을 바꿉니다. 정리한 우선순위는 `--context`·`-H` > `DOCKER_HOST` > `DOCKER_CONTEXT` > `docker context use` 로 저장한 값입니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 555 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 555, 6, '깨진 context 를 우회해서 로컬 컨테이너 보기', '**상황** — 현재 선택된 context 가 `broken`(`ssh://deploy@192.0.2.10`)이라 `docker ps` 가 연결 오류로 멈춥니다. 로컬 데몬에 `webapp` 이라는 컨테이너가 돌고 있는데, **context 선택은 바꾸지 말고** 이번 명령 한 번만 `default` context 로 컨테이너 이름 목록(`docker ps --format "{{.Names}}"`)을 `/tmp/q6.txt` 에 저장하세요.', '`docker` 바로 뒤에 붙이는 전역 옵션 중 context 를 한 번만 지정하는 것이 있습니다. 끝난 뒤 `docker context show` 로 선택이 그대로인지 확인해 보세요.', 'docker --context default ps --format ''{{.Names}}'' > /tmp/q6.txt
cat /tmp/q6.txt
docker context show   # broken 그대로

# --context 는 그 명령 한 번에만 적용된다. use 와 달리 설정 파일을 바꾸지 않는다', '["sh", "-c", "unset DOCKER_HOST; docker context use default >/dev/null 2>&1; docker context rm -f staging alt remote-test broken >/dev/null 2>&1; docker rm -f $(docker ps -aq) >/dev/null 2>&1; rm -rf /tmp/work /tmp/q*.txt; mkdir -p /tmp/work; docker image inspect alpine >/dev/null 2>&1 || docker pull -q alpine >/dev/null 2>&1; true\\ndocker run -d --name webapp alpine sleep 3600 >/dev/null\\ndocker context create broken --docker ''host=ssh://deploy@192.0.2.10'' >/dev/null\\ndocker context use broken >/dev/null\\n"]', '["sh", "-c", "( grep -qx webapp /tmp/q6.txt ) && ( [ \\"$(docker context show)\\" = broken ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "저장된 목록에 webapp 이 있다", "cmd": ["sh", "-c", "grep -qx webapp /tmp/q6.txt"]}, {"label": "선택된 context 는 여전히 broken 이다", "cmd": ["sh", "-c", "[ \\"$(docker context show)\\" = broken ]"]}]', '[{"title": "docker context", "url": "https://docs.docker.com/engine/manage-resources/contexts/"}, {"title": "원격 데몬 보호", "url": "https://docs.docker.com/engine/security/protect-access/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 555 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 555, 7, '원격 데몬을 2375 포트로 열어 두기', '"SSH 설정이 귀찮으니 서버의 도커 데몬을 `tcp://0.0.0.0:2375` 로 열어 두고 `DOCKER_HOST=tcp://서버:2375` 로 쓰자" 는 제안이 나왔습니다. 가장 큰 문제는 무엇인가요?', '서버의 도커 데몬 API 는 컨테이너를 만들고 지울 수 있는 관리자 창구입니다. 이 포트에 닿을 수 있는 사람이 도커에게 무엇을 시킬 수 있는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["속도가 조금 느려진다", "컨테이너가 재시작되면 포트가 바뀐다", "DOCKER_HOST 는 로컬 주소만 받을 수 있다", "인증·암호화가 없어서 네트워크에서 닿는 누구나 데몬에 명령(컨테이너 생성 등)을 내려 서버를 장악할 수 있다"]', 3, '2375 는 평문·무인증 포트라, 닿을 수 있으면 누구나 호스트를 통째로 마운트한 컨테이너를 만드는 등 서버를 장악할 수 있습니다(실제로 공개 2375 가 채굴 악성코드의 표적이 됩니다). 원격 접속은 SSH 기반 `ssh://` context 를 쓰거나, 꼭 TCP 가 필요하면 TLS 상호 인증(보통 2376)과 방화벽 제한을 함께 씁니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 555 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 555, 8, '원격 데몬 context 만들기', '`prod` 라는 이름으로, SSH 로 `ops@192.0.2.20` 에 연결하는 context 를 만드는 명령입니다. 빈칸을 채우세요.', '접속 주소 앞에는 방식(스킴)을 씁니다. 도커 접속 주소는 `--docker` 옵션에 `host=` 로 전달합니다.', NULL, NULL, '[]', 'fill', '["ssh://", "ssh@", "tcp://", "http://"]', NULL, '`ssh://` 스킴이 SSH 를 통한 접속을 뜻합니다. `tcp://` 는 TCP 직접 접속(2375 평문이면 위험)이고, `http://` 는 도커 endpoint 스킴이 아닙니다. `ssh@` 는 형식이 아닙니다.', '[0]', 'docker context create prod --docker "host={0}ops@192.0.2.20"', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 555 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 555, 9, '새 원격 서버를 context 로 쓰기까지', '새 서버를 ssh context 로 쓰려고 합니다. 접속이 안 되는 서버에 context 를 먼저 쓰면 오류만 보이므로, **접속 확인을 먼저** 하고, 마지막에는 안전을 위해 기본 context 로 되돌립니다. 순서대로 놓으세요.', '각 단계가 앞 단계의 무엇을 필요로 하는지 생각해 보세요.', NULL, NULL, '[]', 'order', '["docker context use 로 그 context 를 선택한다", "`ssh 계정@서버 docker ps` 처럼 SSH 로 서버에 접속해 도커가 되는지 확인한다", "docker context create 로 ssh:// 주소의 context 를 만든다", "docker ps 로 원격 컨테이너를 확인한다", "docker context use default 로 기본으로 되돌린다"]', NULL, '먼저 SSH 로 도커가 되는지 확인해 접속·권한 문제를 걸러내고, context 를 만들고, 선택하고, 사용한 뒤 `default` 로 되돌립니다. 되돌리지 않으면 다음에 입력한 `docker rm`·`docker compose down` 이 원격 서버에 실행되는 사고가 납니다.', '[1, 2, 0, 3, 4]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 555 AND order_index = 9);
